def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def to_pair(x, default=(0, 0)):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return [x[0], x[1]]
        return [default[0], default[1]]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = to_pair(observation.get("self_position", (0, 0)))
    ox, oy = to_pair(observation.get("opponent_position", (sx, sy)))
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = [[0, 0], [0, max(0, h - 1)], [max(0, w - 1), 0], [max(0, w - 1), max(0, h - 1)]]
        target = max(corners, key=lambda c: manhattan(c, [ox, oy]))
        return step_toward((sx, sy), tuple(target))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        if targets:
            best = min(targets, key=lambda item: manhattan(to_pair(item), [sx, sy]))
            return step_toward((sx, sy), tuple(to_pair(best)))
        if w and h:
            center = [w // 2, h // 2]
            return step_toward((sx, sy), tuple(center))
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = min(resources, key=lambda item: manhattan(to_pair(item), [sx, sy]))
        return step_toward((sx, sy), tuple(to_pair(best)))

    if ox == sx and oy == sy:
        return [0, 0]

    # Default: move away from opponent, preferring the axis with larger separation.
    dx = clamp_step(sx - ox)
    dy = clamp_step(sy - oy)
    if dx == 0 and dy == 0:
        if w and h:
            return step_toward((sx, sy), (w // 2, h // 2))
        return [0, 0]
    return [dx, dy]

